# skeptic-1 (wht44/ideas), 16 Oct 2026. Independent check of D1's structural claims, from scratch (no shared code):
#  - the q0-singular Lagrangians (q0(x|z) = x.z) are 30, with (distance from L_Z, distance to L_X) counts
#    (0,3):1, (1,2):7, (2,1):7, (2,3):7, (3,2):7, (3,0):1 as Lemma C's B, A1, A2, C2, C3, BK;
#  - their step graph (frame distance 1) is 7-regular and bipartite; B-A1 complete; each A2 has one step to BK;
#    every step changes the distance from L_Z by exactly 1;
#  - O(q0) in Sp(6,2) (generated by the 28 orthogonal transvections) has order 40320, its stabiliser of L_Z has
#    order 1344 (= AGL(3,2)), and P0 * O(q0) is a union of 8 cosets of O(q0) (the 8 "S-gate sectors"), i.e. 322,560
#    of the 1,451,520 elements: 4.5 times fewer than Sp(6,2), against 36 times for the pure subgame.
import itertools
import numpy as np

m = 3
def omega(v, w):   # v = (x|z) as 6-bit tuple
    return (sum(v[i] * w[m + i] + v[m + i] * w[i] for i in range(m))) % 2

def q0(v):
    return sum(v[i] * v[m + i] for i in range(m)) % 2

vecs = [tuple((n >> i) & 1 for i in range(6)) for n in range(64)]
nz = vecs[1:]

def span(gs):
    S = {tuple([0] * 6)}
    for g in gs:
        S |= {tuple((a + b) % 2 for a, b in zip(s, g)) for s in S}
    return frozenset(S)

# all Lagrangians
lag = set()
for a, b, c in itertools.combinations(nz, 3):
    if omega(a, b) or omega(a, c) or omega(b, c): continue
    S = span([a, b, c])
    if len(S) == 8: lag.add(S)
lag = sorted(lag, key=lambda S: sorted(S))
print('Lagrangians:', len(lag))
LZ = span([tuple(1 if j == m + i else 0 for j in range(6)) for i in range(m)])   # {(0|z)}
LX = span([tuple(1 if j == i else 0 for j in range(6)) for i in range(m)])       # {(x|0)}
def dist(A, B): return 3 - {1: 0, 2: 1, 4: 2, 8: 3}[len(A & B)]
sing = [L for L in lag if all(q0(v) == 0 for v in L)]
print('q0-singular Lagrangians:', len(sing))
from collections import Counter
lab = {L: (dist(LZ, L), dist(L, LX)) for L in sing}
print('(dist from L_Z, dist to L_X) counts:', sorted(Counter(lab.values()).items()))
adj = {L: [M for M in sing if dist(L, M) == 1] for L in sing}
print('degrees in the singular step graph:', sorted(Counter(len(v) for v in adj.values()).items()))
# bipartite check by distance parity from L_Z, and depth change along every edge
ok_bip = all((lab[L][0] + lab[M][0]) % 2 == 1 for L in sing for M in adj[L])
ok_step = all(abs(lab[L][0] - lab[M][0]) == 1 for L in sing for M in adj[L])
print('bipartite (edges join opposite depth parity):', ok_bip, '; every edge changes depth by exactly 1:', ok_step)
name = {(0, 3): 'B', (1, 2): 'A1', (2, 1): 'A2', (2, 3): 'C2', (3, 2): 'C3', (3, 0): 'BK'}
E = Counter()
for L in sing:
    for M in adj[L]:
        a, b = name[lab[L]], name[lab[M]]
        if a < b: E[(a, b)] += 1
print('edges between classes:', sorted(E.items()))
a2s = [L for L in sing if lab[L] == (2, 1)]
print('steps from each A2 to BK:', [sum(1 for M in adj[L] if lab[M] == (3, 0)) for L in a2s])
# all Lagrangians at distance 1 from L_Z: how many singular
d1 = [L for L in lag if dist(LZ, L) == 1]
print('depth-1 Lagrangians:', len(d1), 'of which singular:', sum(1 for L in d1 if L in set(sing)))

# group part: 6x6 binary matrices acting on row vectors v -> v M; encode as tuple of 6 row-ints
def mat_from_func(f):
    rows = []
    for i in range(6):
        e = tuple(1 if j == i else 0 for j in range(6))
        img = f(e)
        rows.append(sum(img[j] << j for j in range(6)))
    return tuple(rows)

def apply(Mt, v):
    out = 0
    for i in range(6):
        if v[i]: out ^= Mt[i]
    return tuple((out >> j) & 1 for j in range(6))

def mul(A, Bm):   # v -> (v A) B
    rows = []
    for i in range(6):
        r = A[i]; out = 0
        for j in range(6):
            if (r >> j) & 1: out ^= Bm[j]
        rows.append(out)
    return tuple(rows)

def transvection(u):
    return mat_from_func(lambda w: tuple((wi + omega(u, w) * ui) % 2 for wi, ui in zip(w, u)))

nonsing = [v for v in nz if q0(v) == 1]
print('nonsingular vectors:', len(nonsing))
gens = [transvection(u) for u in nonsing]
I6 = tuple(1 << i for i in range(6))
G = {I6}; fr = [I6]
while fr:
    nx = []
    for g in fr:
        for t in gens:
            p = mul(g, t)
            if p not in G: G.add(p); nx.append(p)
    fr = nx
print('|O(q0)| generated by the 28 orthogonal transvections:', len(G))
def stab(Mt, L):
    return frozenset(apply(Mt, v) for v in L) == L
stZ = [g for g in G if stab(g, LZ)]
print('stabiliser of L_Z in O(q0):', len(stZ))
orbitZ = {frozenset(apply(g, v) for v in LZ) for g in G}
print('orbit of L_Z under O(q0):', len(orbitZ), '= the singular Lagrangians:', orbitZ == set(sing))
# P0 = stabiliser of L_Z in Sp(6,2): order 10752 = 64 * 168. Count |P0 O(q0)| = |P0| |O| / |P0 cap O|
print('|P0 O(q0)| = 10752 * %d / %d = %d; cosets of O(q0): %d; Sp(6,2)/that = %.2f; Sp(6,2)/|O(q0)| = %.0f'
      % (len(G), len(stZ), 10752 * len(G) // len(stZ), 10752 // len(stZ), 1451520 / (10752 * len(G) // len(stZ)),
         1451520 / len(G)))
# h = swap x1 <-> z1 (Hadamard on qubit 1), K = swap all: both in O(q0)?
h = mat_from_func(lambda w: (w[3], w[1], w[2], w[0], w[4], w[5]))
K = mat_from_func(lambda w: (w[3], w[4], w[5], w[0], w[1], w[2]))
print('h in O(q0):', h in G, ' K in O(q0):', K in G, ' h is the transvection of (e1|e1):', h == transvection((1, 0, 0, 1, 0, 0)))
